"""FM-16R: original algebra and complex-number pathways, teacher review pending."""
import sympy as s
from calibration_bank import LEVELS,L
x,h,k=s.symbols('x h k',real=True)
I=s.I; pi=s.pi; R=s.Rational
PATHS={'root-sum-product':'ALG.roots-coefficients.sum-product','quadratic-from-roots':'ALG.related-quadratic.form-equation','polar-to-cartesian':'CPX.conversion.to-cartesian','cartesian-to-polar':'CPX.conversion.to-polar'}
RATIONALES={
'root-sum-product':['Expand linear factors.','Diagnose sign and leading coefficient errors.','Extract sum and product from nonmonic coefficients.','Use symmetric root data to recover coefficients.','Recover a parameter from a root ratio with real-root restrictions.','Classify real root signs and repeated roots across a parameter.'],
'quadratic-from-roots':['Expand factors with specified roots.','Distinguish a monic equation from arbitrary scalar multiples.','Construct monic equation from specified sum and product.','Recover sum and product from two symmetric constraints.','Construct an equation from difference and signed sum.','Classify all monic equations with prescribed real root separation and variable product.'],
'polar-to-cartesian':['Recall exact trigonometric values.','Explain quadrant signs in conversion.','Convert a specified polar number exactly.','Convert two polar numbers and find a Cartesian sum.','Infer a missing modulus and verify a Cartesian constraint.','Reconstruct two positive moduli from a prescribed Cartesian sum; classify existence.'],
'cartesian-to-polar':['Recall Pythagoras for Cartesian coordinates.','Diagnose inverse tangent quadrant ambiguity.','Find exact modulus and principal argument.','Compare polar representations under conjugation.','Recover Cartesian coordinates from modulus and quadrant constraints, then convert.','Classify all polar numbers with fixed modulus and arbitrary real part, handling the argument endpoint.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=v+3;d=2*v+5
 if path=='root-sum-product':
  if l==1:
   P=s.expand((x-a)*(x+b));f=[P];q=f'Expand {L((x-a)*(x+b))}.';ans=L(P);steps=['Multiply both terms in the first bracket by both terms in the second.',f'Collect like terms to obtain {L(P)}.'];hint=['Use the distributive law.','Collect the two linear terms.'];mist='Dropping a negative sign in the constant.'
  elif l==2:
   P=2*x*x+b*x-d;f=[-R(b,2),-R(d,2)];q=f'A student says the roots of {L(P)} = 0 have sum {b} and product {-d}. Explain and correct both claims.';ans=f'Sum {L(f[0])}; product {L(f[1])}.';steps=['Compare the quadratic with a(x-alpha)(x-beta).','The linear coefficient is minus a times the sum; the constant is a times the product.',f'Divide each coefficient by the leading coefficient 2: sum {L(f[0])}, product {L(f[1])}.'];hint=['Do not assume the equation is monic.','Check the sign of the linear coefficient.'];mist='Using coefficients without dividing by the leading coefficient.'
  elif l==3:
   P=a*x*x-d*x+b;f=[R(d,a),R(b,a)];q=f'Without solving the equation {L(P)} = 0, calculate the sum and product of its roots.';ans=f'Sum {L(f[0])}; product {L(f[1])}.';steps=[f'The leading coefficient is {a}, the linear coefficient {-d}, and constant {b}.',f'Use minus linear over leading and constant over leading: {L(f[0])}, {L(f[1])}.'];hint=['Identify all three coefficients.','Apply the two root-coefficient identities.'];mist='Taking the product as the negative constant ratio.'
  elif l==4:
   S=a+b;P=a*b;f=[S,P,-S,P];q=f'A monic quadratic has roots alpha and beta with alpha+beta={S} and (alpha-beta)^2={ (a-b)**2 }. Find the product, then the linear and constant coefficients.';ans=f'Sum {S}; product {P}; coefficients {-S}, {P}.';steps=['Use (alpha-beta)^2=(alpha+beta)^2-4 alpha beta.',f'Thus 4 alpha beta={S*S}-{(a-b)**2}, giving product {P}.',f'The linear coefficient is {-S} and the constant is {P}.'];hint=['Relate the two squares.','Use the monic coefficient identities.'];mist='Confusing the square of a difference with the difference of squares.'
  elif l==5:
   S=a*(b+1);P=b*a*a;f=[S,P,a,a*b];q=f'The quadratic x^2-kx+{P}=0 has two positive roots, one {b} times the other. Find k and both roots, proving uniqueness.';ans=f'k={S}; roots {a}, {a*b}.';steps=[f'Write the smaller positive root as r and the larger as {b}r.',f'The product gives {b}r^2={P}; positivity forces r={a}.',f'The root sum is ({b}+1)r={S}, so k={S}.', 'Both roots satisfy the ratio and product, and the positive square root is unique.'];hint=['Use a single unknown for the smaller root.','The product fixes its square; use positivity.'];mist='Keeping a negative root pair despite the positive-root condition.'
  else:
   lo=b-2*a;hi=b+2*a;f=[lo,hi,a,-a];q=f'For every real k classify the roots of {L(x*x-(k-b)*x+a*a)} = 0 as non-real, repeated positive/negative, or distinct positive/negative. Explain why opposite signs and zero roots are impossible.';ans=f'k<{lo}: two distinct negative; k={lo}: repeated {-a}; {lo}<k<{hi}: non-real; k={hi}: repeated {a}; k>{hi}: two distinct positive.';steps=[f'Root sum k-{b}, product {a*a}>0; real roots have the same nonzero sign.',f'The discriminant is (k-{b})^2-{4*a*a}, zero exactly at k={lo} or {hi}.',f'It is negative between the thresholds, so roots there are non-real conjugates.',f'For k<{lo} the sum is negative and the roots are distinct negative; for k>{hi} the sum is positive and roots distinct positive.',f'At the thresholds the repeated root is half the sum: {-a} or {a} respectively. These disjoint intervals and endpoints exhaust real k.'];hint=['First determine when roots are real.','Use the product and sum together to decide their signs.'];mist='Using the sign of the root sum before establishing that roots are real.'
 elif path=='quadratic-from-roots':
  if l==1:
   P=s.expand((x-a)*(x-d));f=[P];q=f'Write the monic quadratic equation with roots {a} and {d} by expanding its linear factors.';ans=L(P)+' = 0';steps=[f'Use factors (x-{a})(x-{d}).',f'Expansion gives {L(P)} = 0.'];hint=['Each root gives a linear factor.','The leading coefficient must be one.'];mist='Using x plus the root as its factor.'
  elif l==2:
   P=s.expand((x+a)*(x-b));f=[P,False];q=f'A student claims {L(2*P)} = 0 is the only equation with roots {-a} and {b}. Give the monic equation and explain why the claim is false.';ans=L(P)+' = 0; not unique without a leading coefficient.';steps=[f'The monic equation is (x+{a})(x-{b})=0, giving {L(P)}=0.','Multiplying both sides by any nonzero real constant leaves the root set unchanged.','Only the monic polynomial is unique; the original equation is one nonmonic example.'];hint=['Expand the factors with leading coefficient one.','Does multiplying by a nonzero constant change the zeros?'];mist='Confusing unique roots with unique coefficients.'
  elif l==3:
   S=d;P=-a*b;F=x*x-S*x+P;f=[F];q=f'Construct the monic quadratic equation whose roots have sum {S} and product {P}, without finding either root.';ans=L(F)+' = 0';steps=['Use x^2 minus (sum)x plus product.',f'Substitute the supplied values: {L(F)}=0.'];hint=['Use the root-coefficient identities in reverse.','The product is negative.'];mist='Negating both the sum and product.'
  elif l==4:
   S=a-b;P=-a*b;F=x*x-S*x+P;f=[S,P,F];q=f'Two roots alpha,beta satisfy alpha+beta={S} and alpha^2+beta^2={a*a+b*b}. Construct their monic quadratic and verify its discriminant is positive.';ans=f'Sum {S}; product {P}; {L(F)}=0.';steps=[f'Use alpha^2+beta^2=(alpha+beta)^2-2 alpha beta; product is ({S*S}-{a*a+b*b})/2={P}.',f'The monic equation is {L(F)}=0.',f'Its discriminant is {S*S-4*P}>0, so two distinct real roots exist.'];hint=['Express sum of squares using sum and product.','Check the discriminant of your constructed equation.'];mist='Taking the product as half the sum of squares.'
  elif l==5:
   S=b+d;D=d-b;P=b*d;F=x*x-S*x+P;f=[P,F];q=f'Two real roots have sum {S} and absolute difference {D}. Construct their monic quadratic without choosing an order for the roots, and prove uniqueness.';ans=f'Product {P}; {L(F)}=0.';steps=[f'The squared difference is {D*D}.',f'Use 4 alpha beta=(alpha+beta)^2-(alpha-beta)^2={S*S}-{D*D}, giving {P}.',f'The monic equation is {L(F)}=0.',f'The discriminant is {D*D}>0 and the supplied sum and squared difference uniquely fix both coefficients.'];hint=['Square the absolute difference.','Find the product before constructing the equation.'];mist='Treating the absolute difference as a signed difference and losing a root ordering.'
  else:
   bound=-R(d*d,4);S=s.sqrt(d*d+4*h);F=x*x-S*x+h;G=x*x+S*x+h;f=[bound,F,G];q=f'For each real h find every monic real quadratic whose two real roots have absolute difference {d} and product h. Classify the number of distinct equations and justify all boundary cases.';ans=f'h<{L(bound)}: none; h={L(bound)}: {L(x*x+bound)}=0; h>{L(bound)}: {L(F)}=0 or {L(G)}=0.';steps=[f'Let S be the root sum. The identity S^2-4h={d*d} forces S^2={d*d}+4h.',f'If h<{L(bound)}, no real S exists; if equal, S=0 and the only equation is {L(x*x+bound)}=0.',f'If h>{L(bound)}, S has two distinct opposite values, so the two equations are {L(F)}=0 and {L(G)}=0.',f'In each constructed equation the discriminant is exactly {d*d}>0, giving two real roots with absolute difference {d}, and the constant guarantees product h.', 'Conversely any admissible monic equation must have one of these sums and constant h, so none are omitted.'];hint=['Treat the root sum as unknown, not either individual root.','Check when its square is nonnegative; verify the resulting discriminant.'];mist='Counting the two signs twice when the square root is zero.'
 elif path=='polar-to-cartesian':
  th=[pi/6,pi/4,pi/3][v-1];r=2*a;Z=lambda m,t:s.simplify(s.expand_complex(m*(s.cos(t)+I*s.sin(t))))
  if l==1:
   f=[s.cos(th),s.sin(th)];q=f'Give exact values of cosine and sine of {L(th)} radians.';ans=', '.join(L(e) for e in f);steps=['Use the exact right-triangle trigonometric ratios.',f'Cosine is {L(f[0])} and sine is {L(f[1])}.'];hint=['Use a standard special-angle triangle.','Cosine is adjacent over hypotenuse.'];mist='Interchanging sine and cosine.'
  elif l==2:
   T=pi-th;f=[Z(r,th),Z(r,T)];q=f'A student converts modulus {r}, argument {L(T)} to {L(f[0])}. Explain the quadrant error and give the correct Cartesian form.';ans=L(f[1]);steps=[f'The angle {L(T)} is in quadrant II: cosine negative, sine positive.',f'Use real part {r}cos(theta) and imaginary component {r}sin(theta).',f'The correct form is {L(f[1])}.'];hint=['Locate the angle before evaluating trig functions.','Check both coordinate signs.'];mist='Using the reference angle without applying quadrant signs.'
  elif l==3:
   T=-pi+th;f=[Z(r,T)];q=f'Convert the complex number with modulus {r} and argument {L(T)} radians to exact Cartesian form.';ans=L(f[0]);steps=[f'Use z={r}(cos(theta)+i sin(theta)).',f'The angle {L(T)} lies in quadrant III, so both components are negative.',f'Evaluating gives {L(f[0])}.'];hint=['Use cosine for the real part.','Use sine for the imaginary component.'];mist='Treating a negative angle as a positive reference angle.'
  elif l==4:
   A=Z(r,th);B=Z(b,-th);f=[A,B,s.simplify(A+B)];q=f'Convert two complex numbers with polar data (modulus, argument) ({r}, {L(th)}) and ({b}, {L(-th)}) to Cartesian form, then calculate their sum exactly.';ans=f'{L(A)}, {L(B)}; sum {L(f[2])}.';steps=[f'Convert the first number: {L(A)}.',f'Convert the second number: {L(B)}.',f'Add real and imaginary components separately to obtain {L(f[2])}.'];hint=['Convert each number separately.','Do not add moduli and arguments to add complex numbers.'];mist='Applying polar multiplication rules to addition.'
  elif l==5:
   T=pi-th;A=Z(r,T);f=[r,A];q=f'A nonzero complex number has principal argument {L(T)} and real part {L(s.re(A))}. Recover its modulus and Cartesian form, explaining why there is exactly one solution.';ans=f'Modulus {r}; {L(A)}.';steps=[f'Write real part m cos({L(T)}).',f'The cosine is {L(s.cos(T))}, nonzero, so division fixes m={r}>0.',f'Use the sine for the imaginary component; z={L(A)}.', 'The modulus is uniquely determined and the fixed argument fixes the other component.'];hint=['Use the real-part equation to solve for modulus.','Check that the recovered modulus is positive.'];mist='Using a negative modulus to compensate for a quadrant error.'
  else:
   C=s.cos(th);S=s.sin(th);m=s.simplify((k/S+h/C)/2);n=s.simplify((k/S-h/C)/2);f=[m,n,s.tan(th),s.expand(m*(C+I*S)),s.expand(n*(-C+I*S))];q=f'Nonzero complex numbers z,w have principal arguments {L(th)} and {L(pi-th)} respectively. For all real h,k determine when z+w=h+ki is possible, and recover both moduli and Cartesian forms. Explain the boundary where a modulus would vanish.';ans=f'Exists uniquely if k>{L(s.tan(th))}|h|. Moduli {L(m)}, {L(n)}; z={L(f[3])}, w={L(f[4])}.';steps=[f'Let the positive moduli be m,n. The Cartesian forms are m({L(C)}+i{L(S)}) and n(-{L(C)}+i{L(S)}).',f'Comparing real and imaginary parts gives (m-n)cos(theta)=h and (m+n)sin(theta)=k.',f'Both trig values are positive, so solving gives m={L(m)}, n={L(n)} uniquely.',f'Both moduli are strictly positive exactly when k/sin(theta)>|h|/cos(theta), equivalently k>{L(s.tan(th))}|h|.',f'Then the Cartesian forms are {L(f[3])}, {L(f[4])}. On the boundary at least one modulus is zero, violating the nonzero requirement; below it at least one modulus is nonpositive. Every case follows from the unique linear solution.'];hint=['Express both polar numbers in Cartesian form with unknown positive moduli.','Solve the two linear equations and impose both positivity inequalities.'];mist='Allowing a zero or negative modulus for a number with a specified principal argument.' 
 else:
  th=[pi/6,pi/4,pi/3][v-1];r=2*a;A=s.simplify(r*s.cos(th));B=s.simplify(r*s.sin(th))
  if l==1:
   f=[s.sqrt(a*a+b*b)];q=f'Find the distance from the origin to the Cartesian point ({a},{b}).';ans=L(f[0]);steps=['Use Pythagoras on the horizontal and vertical displacements.',f'The distance is {L(f[0])}.'];hint=['Draw a right triangle.','Square both components before adding.'];mist='Adding coordinate magnitudes instead of their squares.'
  elif l==2:
   f=[-th,pi-th];q=f'A student uses arctan(y/x) to assign argument {L(-th)} to z={L(-A+I*B)}. Explain the error and give the principal argument in (-pi,pi].';ans=L(f[1]);steps=['The ratio y/x is negative but the point is in quadrant II.',f'The inverse tangent gives {L(-th)}, which points to quadrant IV.',f'Add pi to obtain {L(pi-th)}.'];hint=['Check the signs of x and y.','Tangent has period pi.'];mist='Using inverse tangent without a quadrant correction.'
  elif l==3:
   f=[r,-pi+th];q=f'Convert {L(-A-I*B)} to exact modulus and principal argument in (-pi,pi].';ans=f'Modulus {r}, argument {L(f[1])}.';steps=[f'Modulus is sqrt(x^2+y^2)={r}.',f'The reference angle is {L(th)} and both coordinates are negative.',f'The principal argument is {L(-pi+th)}.'];hint=['Calculate modulus independently.','Use the quadrant III angle in the required range.'];mist='Reporting the positive angle outside the principal range.'
  elif l==4:
   f=[r,pi-th,r,-pi+th];q=f'Convert z={L(-A+I*B)} and its conjugate to exact modulus-argument form in (-pi,pi]. Explain the geometric relation.';ans=f'z: ({r},{L(f[1])}); conjugate: ({r},{L(f[3])}).';steps=[f'Both moduli are {r} because negating y leaves x^2+y^2 unchanged.',f'Quadrant II gives z argument {L(pi-th)}.',f'Conjugation reflects across the real axis, giving argument {L(-pi+th)} in quadrant III.'];hint=['Conjugation changes only the imaginary sign.','Determine the quadrant for each number.'];mist='Negating the modulus along with the argument.'
  elif l==5:
   f=[-B,-pi+th];q=f'A complex number has modulus {r}, real part {L(-A)}, and strictly negative imaginary part. Recover its imaginary component and exact principal argument, proving uniqueness.';ans=f'Imaginary component {L(-B)}; argument {L(f[1])}.';steps=[f'Use y^2={r*r}-({L(A)})^2={L(s.simplify(B*B))}.',f'The negative imaginary component selects y={L(-B)} uniquely.',f'Both coordinates are negative; the reference angle is {L(th)}, giving principal argument {L(-pi+th)}.'];hint=['Use the modulus equation to recover y.','Use the given sign before finding the argument.'];mist='Retaining the positive imaginary component despite the constraint.'
  else:
   T=s.acos(h/r);f=[-r,r,T,-T,pi,0];q=f'For every real h find all complex numbers of modulus {r} and real part h, giving their principal arguments in (-pi,pi]. Classify how many numbers exist, and explain why the two boundary cases must be handled separately.';ans=f'|h|>{r}: none; h={r}: argument 0; h={-r}: argument pi; -{r}<h<{r}: arguments {L(T)} and {L(-T)}, both with modulus {r}.';steps=[f'From x=h and modulus {r}, y^2={r*r}-h^2.',f'If |h|>{r}, the right side is negative, so no real y exists.',f'If -{r}<h<{r}, y has two distinct opposite signs. The upper-half-plane argument is {L(T)} in (0,pi), the lower is its negative.',f'If h={r}, y=0 gives positive real number and argument 0. If h={-r}, y=0 gives negative real number and argument pi, not -pi in the required range.', 'The two interior signs and the two boundary cases exhaust all real y, proving completeness.'];hint=['Start with the Cartesian modulus relation.','Use the sign of y and the specified principal interval.'];mist='Counting pi and minus pi as separate solutions on the negative real axis.'
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hint,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[e if type(e) is bool else str(e) for e in f],likely_mistake=mist,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
